 function rendererControls(){const root=q('.l3-pilot');if(root)root.dataset.renderer=actualView;for(const b of host.querySelectorAll('[data-l3-view]'))b.setAttribute('aria-pressed',String(b.dataset.l3View===(actualView==='loading'?requestedView:actualView)));for(const b of host.querySelectorAll('[data-l3-camera-mode]'))b.hidden=actualView!=='3d';const label=q('#l3ViewStatus');if(label)label.textContent=viewNotice||(actualView==='loading'?t('Đang mở bàn 3D…','Opening the 3D bench…'):actualView==='3d'?t('Kéo dụng cụ để thao tác. Kéo vùng trống để xoay góc nhìn; dùng hai ngón để xoay và thu phóng.','Drag an instrument to use it. Drag empty space to orbit; use two fingers to move and zoom.'):t('Sơ đồ 2D: kéo dụng cụ hoặc dùng các nút di chuyển chính xác.','2D diagram: drag instruments or use the precise movement controls.'));}
