 function input(event){const node=event.target;if(node.id==='l3StudentTemperature'||node.dataset.l3Calc||node.dataset.l3Config||node.dataset.l3Mass){captureDrafts();saveSoon();}if(node.dataset.l3Field==='cup-angle')rotate('cup',Number(node.value)*Math.PI/180);if(node.dataset.l3Note){trial()[node.dataset.l3Note]=node.value;drawNotebook();saveSoon();}if(node.dataset.l3Field==='speed')speed=Number(node.value);if(node.dataset.l3Field==='mode'){session.mode=node.value;const hints=q('#l3Guided');hints.open=node.value==='guided';saveSoon();}}
 function change(event){if(event.target.id==='l3Import')importFile(event.target.files[0]);}
 function captureDrafts(){const temperature=q('#l3StudentTemperature');if(!temperature)return;session.drafts={temperature:temperature.value,masses:Object.fromEntries([...host.querySelectorAll('[data-l3-mass]')].map(n=>[n.dataset.l3Mass,n.value])),calculation:Object.fromEntries([...host.querySelectorAll('[data-l3-calc]')].map(n=>[n.dataset.l3Calc,n.value])),config:Object.fromEntries([...host.querySelectorAll('[data-l3-config]')].map(n=>[n.dataset.l3Config,n.value]))};}
